-- Seed practical coding questions for every battle difficulty. Idempotent by stable UUID.
on conflict (id) do update set question=excluded.question,image_url=excluded.image_url,option_a=excluded.option_a,option_b=excluded.option_b,option_c=excluded.option_c,option_d=excluded.option_d,correct_answer=excluded.correct_answer,explanation=excluded.explanation,category=excluded.category,difficulty=excluded.difficulty,level=excluded.level,is_active=excluded.is_active,updated_at=now();
