values
  ('57862b19-97e5-5c69-b875-5d1fe368c1b8', 'Saat tombol bendera hijau di Scratch diklik, apa yang biasanya terjadi?', '/images/questions/scratch-events.svg', 'Program mulai berjalan', 'Sprite langsung dihapus', 'Komputer mati', 'Proyek tersimpan otomatis', 'A', 'Blok peristiwa bendera hijau menjalankan rangkaian blok yang terhubung.', 'scratch', 'easy', 'easy', true),
  ('b1710e73-4d25-543a-8d92-5272c9b53b9f', 'Blok “gerak 10 langkah” membuat sprite melakukan apa?', '/images/questions/scratch-motion.svg', 'Bergerak maju 10 langkah', 'Berputar 10 kali', 'Menunggu 10 detik', 'Mengubah ukuran 10%', 'A', 'Blok gerak mengubah posisi sprite.', 'scratch', 'easy', 'easy', true),
  ('b05d8b1d-6ebf-57eb-84b7-f19ecaafb56f', 'Apa fungsi blok “ulangi 5 kali”?', '/images/questions/scratch-loop.svg', 'Menjalankan blok di dalamnya sebanyak lima kali', 'Menghentikan semua suara', 'Menghapus lima sprite', 'Menunggu lima menit', 'A', 'Perulangan menjalankan perintah di dalamnya beberapa kali.', 'scratch', 'easy', 'easy', true),
  ('3bdd4e95-303b-5f91-91b8-a996d5a3e5c0', 'Blok “katakan Halo selama 2 detik” digunakan untuk apa?', '/images/questions/scratch-events.svg', 'Menampilkan balon kata selama 2 detik', 'Memutar suara Halo dua kali', 'Mengganti nama proyek', 'Menggerakkan sprite 2 langkah', 'A', 'Blok tampilan tersebut menampilkan teks sementara pada sprite.', 'scratch', 'easy', 'easy', true),
  ('2a6ec4c6-6b20-5855-a4ef-be141577ea65', 'Apa yang dimaksud dengan sprite di Scratch?', '/images/questions/scratch-motion.svg', 'Karakter atau objek yang dapat diprogram', 'Nama untuk latar belakang saja', 'Jenis kabel komputer', 'Tombol untuk menyimpan', 'A', 'Sprite adalah objek yang dapat diberi kostum dan perilaku.', 'scratch', 'easy', 'easy', true),
  ('4320c67b-d290-5da8-b7c8-d59b69e9bbc8', 'Blok “tunggu 1 detik” akan membuat program…', '/images/questions/scratch-events.svg', 'Berhenti sebentar sebelum lanjut', 'Berjalan dua kali lebih cepat', 'Menghapus blok berikutnya', 'Berpindah ke proyek lain', 'A', 'Blok tunggu memberi jeda sebelum perintah berikutnya.', 'scratch', 'easy', 'easy', true),
  ('b3c38e2a-f018-59ad-afaf-a3a338bdacf7', 'Dalam Scratch, blok “jika menyentuh tepi, pantulkan” membantu sprite untuk…', '/images/questions/block-logic.svg', 'Berbalik arah saat mencapai tepi panggung', 'Mengganti warna panggung', 'Membuat salinan proyek', 'Menghapus tepi layar', 'A', 'Blok pantulkan membalik arah gerak saat menyentuh batas.', 'scratch', 'easy', 'easy', true),
  ('c2c604cb-4d1f-5a9f-81f0-088050d66cf3', 'Apa arti urutan blok dalam program?', '/images/questions/scratch-events.svg', 'Urutan perintah yang dijalankan komputer', 'Daftar gambar di folder', 'Nama akun pengguna', 'Jumlah warna pada layar', 'A', 'Program menjalankan instruksi mengikuti urutannya.', 'block_coding', 'easy', 'easy', true),
  ('df6f4d19-8391-50f5-87e9-b0f769842cea', 'Variabel sederhana biasanya dipakai untuk menyimpan…', '/images/questions/block-logic.svg', 'Nilai seperti skor atau nama', 'Bentuk monitor', 'Kabel jaringan', 'Warna keyboard', 'A', 'Variabel menyimpan data yang dapat dipakai dan diubah oleh program.', 'block_coding', 'easy', 'easy', true),
  ('48d19abf-0b14-5475-aa42-c8bd6579979c', 'Apa hasil dari 3 + 2?', '/images/questions/block-logic.svg', '5', '6', '4', '32', 'A', 'Operator tambah menjumlahkan kedua angka.', 'programming_basics', 'easy', 'easy', true),
  ('52bd403e-e49a-5ddf-83d8-e1c6dccff348', 'Blok “selamanya” akan…', '/images/questions/scratch-loop.svg', 'Mengulang blok di dalamnya terus sampai program dihentikan', 'Mengulang tepat satu kali', 'Menunggu tanpa batas lalu lanjut', 'Menghapus semua sprite', 'A', 'Perulangan selamanya terus mengulang selama skrip berjalan.', 'scratch', 'easy', 'easy', true),
  ('c7525e28-2a71-529b-9bb4-fe85a6dc1681', 'Perintah “jika… maka…” dipakai untuk…', '/images/questions/block-logic.svg', 'Memilih aksi berdasarkan suatu kondisi', 'Mengulang aksi tanpa henti', 'Mengganti nama file', 'Menyimpan gambar', 'A', 'Kondisi menentukan apakah perintah tertentu dijalankan.', 'programming_basics', 'easy', 'easy', true),
  ('195c1b72-99f2-57ff-a47f-e360c856804c', 'Skrip mengulang 4 kali perintah “gerak 10 langkah”. Berapa total langkah gerak?', '/images/questions/scratch-loop.svg', '40 langkah', '14 langkah', '10 langkah', '4 langkah', 'A', 'Empat pengulangan dikali sepuluh langkah menghasilkan empat puluh langkah.', 'scratch', 'medium', 'medium', true),
  ('41957986-1c39-527a-ba8d-83717d04d5d0', 'Sprite harus bergerak hanya saat tombol spasi ditekan. Blok apa yang tepat untuk memulai skrip?', '/images/questions/scratch-events.svg', 'Ketika tombol spasi ditekan', 'Ketika bendera hijau diklik', 'Ulangi selamanya', 'Tunggu 1 detik', 'A', 'Gunakan blok peristiwa ketika tombol tertentu ditekan.', 'scratch', 'medium', 'medium', true),
  ('ba58c72b-d1a1-503c-9d53-2c53bf644d16', 'Skor dimulai dari 0 dan bertambah 1 setiap kali koin diambil. Berapa skor setelah 6 koin?', '/images/questions/block-logic.svg', '6', '5', '7', '1', 'A', 'Setiap koin menambah satu, jadi enam koin menghasilkan skor enam.', 'block_coding', 'medium', 'medium', true),
  ('65bd5dbc-2513-59ab-943c-c6c1d75141fd', 'Apa yang terjadi jika blok “jika menyentuh warna merah” berisi perintah “mainkan suara”?', '/images/questions/block-logic.svg', 'Suara dimainkan saat sprite menyentuh warna merah', 'Suara selalu dimainkan sebelum mulai', 'Sprite berubah menjadi merah', 'Program berhenti permanen', 'A', 'Kondisi menjalankan perintah ketika sentuhan warna terpenuhi.', 'scratch', 'medium', 'medium', true),
  ('458f7210-9b7e-5edc-882d-87536447a856', 'Sebuah loop berjalan 3 kali dan menambah variabel skor sebesar 2 setiap kali. Berapa pertambahannya?', '/images/questions/scratch-loop.svg', '6', '5', '3', '9', 'A', 'Nilainya bertambah 2 sebanyak 3 kali, yaitu 6.', 'programming_basics', 'medium', 'medium', true),
  ('9a807026-9a41-53ea-b10b-5e5eed9f5c22', 'Apa manfaat memecah program panjang menjadi beberapa blok atau prosedur kecil?', '/images/questions/block-logic.svg', 'Lebih mudah dibaca, digunakan ulang, dan diperbaiki', 'Komputer tidak perlu menjalankan instruksi', 'Semua variabel otomatis terhapus', 'Program pasti memakai lebih banyak gambar', 'A', 'Bagian kecil membantu menyusun dan merawat program.', 'block_coding', 'medium', 'medium', true),
  ('15ffbed7-27f5-5fe2-be94-e1c2900fe97e', 'Variabel nyawa bernilai 3. Setiap menyentuh musuh berkurang 1. Apa nilai nyawa setelah dua kali menyentuh musuh?', '/images/questions/block-logic.svg', '1', '2', '3', '0', 'A', 'Nyawa berkurang dua kali: 3 dikurangi 2 sama dengan 1.', 'scratch', 'hard', 'hard', true),
  ('6aa7c050-198b-527d-bee1-e795095d0287', 'Loop berjalan selama skor < 5 dan menambah skor 1 dari nilai awal 2. Berapa kali loop berjalan?', '/images/questions/scratch-loop.svg', '3 kali', '2 kali', '4 kali', '5 kali', 'A', 'Nilai berubah 2, 3, 4, lalu 5; kondisi berhenti setelah tiga pengulangan.', 'programming_basics', 'hard', 'hard', true),
  ('36e663f8-bb67-55c7-9c5f-c3616bbeae20', 'Skrip memeriksa “jika menyentuh koin” lalu mengubah skor +1. Mengapa kondisi tersebut perlu diperiksa berulang?', '/images/questions/block-logic.svg', 'Agar koin yang disentuh kemudian tetap terdeteksi', 'Agar sprite selalu diam', 'Agar proyek tersimpan otomatis', 'Agar variabel berubah menjadi teks', 'A', 'Pemeriksaan berulang mendeteksi tabrakan yang dapat terjadi kapan saja.', 'scratch', 'hard', 'hard', true),
  ('a008da99-0773-5eac-936d-4727809eafaa', 'Apa keluaran dari logika: jika angka genap maka tampilkan “A”, jika tidak tampilkan “B”, untuk angka 7?', '/images/questions/block-logic.svg', 'B', 'A', 'A dan B', 'Tidak ada keluaran', 'A', 'Tujuh bukan bilangan genap, sehingga cabang jika tidak dijalankan.', 'block_coding', 'hard', 'hard', true),
  ('2859053b-d6a9-5560-9259-d06b628dae51', 'Variabel x bernilai 4. Jalankan x = x + 3, lalu x = x * 2. Berapa nilai akhir x?', '/images/questions/block-logic.svg', '14', '11', '8', '7', 'A', 'Pertama x menjadi 7, lalu 7 dikali 2 menjadi 14.', 'programming_basics', 'hard', 'hard', true),
  ('6b4db04a-9b10-520d-b8dc-84f9f4d48adb', 'Sebuah sprite bergerak 5 langkah sebanyak 8 kali, lalu mundur 10 langkah. Berapa perpindahan akhirnya?', '/images/questions/scratch-loop.svg', '30 langkah maju', '40 langkah maju', '50 langkah maju', '10 langkah mundur', 'A', 'Delapan kali lima adalah 40; setelah mundur 10, perpindahannya 30 langkah maju.', 'scratch', 'hard', 'hard', true)
